              <div>
                <div className="text-slate-400 font-semibold mb-1">Actual Output:</div>
                <div className={`p-2.5 rounded-lg border whitespace-pre-wrap ${
                  testCases[activeTab].passed
                    ? 'bg-dark-800 border-dark-700 text-emerald-300'
                    : 'bg-rose-950/30 border-rose-500/30 text-rose-300'
                }`}>
                  {testCases[activeTab].actual || '[No output or error]'}
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

